Definition icpt_frame (m : mem) (usp : Z) (ra s0 s1 s2 s3 s4 s5 : word) : Prop :=
  rw_cells asegs m (usp + -56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
  /\ (exists jp, rw_cells asegs m (usp + -64) [CB 8 jp])
  /\ rw_cells asegs m (usp + -72) [C8 (Z_to_bv 64 usp)]
  /\ (exists ws, u64arr asegs m (usp + -2112) ws /\ length ws = 255%nat)
  /\ (exists w, rw_cells asegs m (usp + -2128) [C8 (Z_to_bv 64 (usp + -2112)); C8 w]).

